WITH m AS (SELECT id, role, content, COALESCE(intent,'') AS intent, COALESCE(lesson_code,'') AS lesson_code, COALESCE(link,'') AS link, COALESCE(links,'') AS links, at, LAG(id) OVER (ORDER BY id) AS prev_id, LAG(role) OVER (ORDER BY id) AS prev_role FROM tutor_message WHERE learner = :learner AND subject_id = CAST(:subject_id AS INTEGER)), r AS (SELECT *, CASE WHEN role = 'teacher' AND prev_role IS NOT NULL AND prev_role <> 'teacher' AND intent <> 'summary' THEN 1 ELSE 0 END AS merged FROM m), rounds AS (SELECT h.id AS id, CASE WHEN h.role = 'user' THEN h.content ELSE '' END AS ask, CASE WHEN t.id IS NOT NULL THEN t.content WHEN h.role = 'teacher' THEN h.content ELSE '' END AS reply, h.intent AS intent, h.at AS at FROM r h LEFT JOIN r t ON t.prev_id = h.id AND t.merged = 1 WHERE h.merged = 0), f AS (SELECT id FROM rounds WHERE (trim(:keyword) = '' OR instr(lower(ask), lower(trim(:keyword))) > 0 OR instr(lower(reply), lower(trim(:keyword))) > 0) AND (:date_from = '' OR substr(at, 1, 10) >= :date_from) AND (:date_to = '' OR substr(at, 1, 10) <= :date_to) AND (:intent = '' OR intent = :intent)) SELECT total, MAX(1, (total + CAST(:ps AS INTEGER) - 1) / CAST(:ps AS INTEGER)) AS page_count FROM (SELECT COUNT(*) AS total FROM f)
